SELECT FROM sys_menu WHERE id IN
#{id}
ORDER BY sort_no ASC, id ASC

SELECT FROM sys_menu WHERE id IN
#{id}
AND status = 1 ORDER BY sort_no ASC, id ASC

SELECT COUNT(1)
FROM sys_menu
WHERE path = #{path}

    AND id != #{excludeId}

SELECT COUNT(1)
FROM sys_menu
WHERE permission_code = #{permissionCode}
  AND permission_code IS NOT NULL
  AND permission_code != ''

    AND id != #{excludeId}

SELECT COUNT(1)
FROM sys_menu
WHERE parent_id = #{parentId}
